// Input: array of URLs from Link Gopher
const urls = items.map(item => item.json.url);
return urls.map(url => ({ json: { url, original_url: url, attempt: 1 } }));

// Handle failed download
const errorMsg = $json.error ? $json.error.message : 'Unknown error';
return [
  {
    json: {
      ...$json,
      status: 'download_failed',
      error: errorMsg,
      error_type: 'download',
      timestamp: new Date().toISOString(),
      retryable: $json.attempt < 3
    }
  }
];

// Extract state and session from filename
const filename = $json.url.split('/').pop();
const match = filename.match(/^([A-Z]{2})_(\d+[A-Za-z0-9-]*)_json_/);
const state = match ? match[1] : 'unknown';
const session = match ? match[2] : 'unknown';

return {
  ...$json,
  state,
  session,
  filename,
  timestamp: new Date().toISOString()
};

// Route to appropriate storage
const state = $json.state.toLowerCase();
const session = $json.session;
const filename = $json.filename;

// Store in harvy-artifacts bucket
const r2Path = `openstates/${state}/${session}/${filename}`;

return [
  {
    json: {
      ...$json,
      storage_type: 'r2',
      r2_bucket: 'harvy-artifacts',
      r2_path: r2Path,
      content_type: 'application/json'
    }
  },
  {
    json: {
      ...$json,
      storage_type: 'basin',
      basin_path: 'harvyql_stream',
      data: $json.json
    }
  }
];

// Handle R2 upload failure
const errorMsg = $json.error ? $json.error.message : 'Unknown R2 error';
return [
  {
    json: {
      ...$json,
      status: 'r2_upload_failed',
      error: errorMsg,
      error_type: 'r2_upload',
      timestamp: new Date().toISOString()
    }
  }
];

// Handle Basin send failure
const errorMsg = $json.error ? $json.error.message : 'Unknown Basin error';
return [
  {
    json: {
      ...$json,
      status: 'basin_ingest_failed',
      error: errorMsg,
      error_type: 'basin_ingest',
      timestamp: new Date().toISOString()
    }
  }
];

// Success tracking
const results = [];

if ($json.status === 'success' || $json.status === 'r2_upload_success' || $json.status === 'basin_ingest_success') {
  if ($json.storage_type === 'r2') {
    results.push({
      json: {
        ...$json,
        status: 'r2_upload_success',
        message: `Uploaded to harvy-artifacts/openstates/${$json.state}/${$json.session}/${$json.filename}`
      }
    });
  }

  if ($json.storage_type === 'basin') {
    results.push({
      json: {
        ...$json,
        status: 'basin_ingest_success',
        message: `Sent to Basin harvyql_stream`
      }
    });
  }
}

return results;

// Aggregate all failures
const failures = items.filter(item => item.json.status && item.json.status.includes('_failed'));

if (failures.length === 0) {
  return [{ json: { message: 'No failures detected', success_count: items.length } }];
}

const errorTypes = {};
failures.forEach(item => {
  const errorType = item.json.error_type || 'unknown';
  if (!errorTypes[errorType]) {
    errorTypes[errorType] = [];
  }
  errorTypes[errorType].push(item.json);
});

return [{ json: { failures, errorTypes, total_failures: failures.length, total_processed: items.length } }];

// Manual retry logic
if ($json.retryable && $json.error_type === 'download') {
  const newUrl = $json.url;
  return [
    {
      json: {
        ...$json,
        url: newUrl,
        attempt: $json.attempt + 1,
        status: 'queued_for_retry'
      }
    }
  ];
}

return [];

// Log to console for debugging
console.log(`[OpenStates Ingest] Status: ${$json.status || 'unknown'}`);
if ($json.error) {
  console.error(`[OpenStates Ingest] Error: ${$json.error}`);
}
return [items[0]];
